// @ts-check
/**
 * Read access to the block catalog (assets/composer/catalog.json, generated by tools/composer_catalog.py).
 * No DOM dependency.
 */

import { makeEnv, tryEvaluate } from './expr.js';
import { initialValue, sameValue } from './generics.js';

export const CATALOG_FORMAT = 'open-space-composer-catalog';
export const CATALOG_VERSION = 1;

/** @typedef {import('./generics.js').GenericDef} GenericDef */

/**
 * @typedef {object} TypeDef
 * @property {string} id
 * @property {string} name
 * @property {string} family
 * @property {'stream'|'bus'|'pins'|'event'} kind
 * @property {string} color
 * @property {string} description
 * @property {Record<string, {dir: 'in'|'out', optional?: boolean}>} [signals]
 * @property {'in'|'out'|'mixed'} [fields]
 * @property {{type: string, sideband?: string, note?: string}[]} [accepts]
 * @property {{type: string, via: string}[]} [bridges]
 * @property {boolean} [generic]
 */

/**
 * @typedef {object} SidebandField
 * @property {string} name
 * @property {string} label
 * @property {number} lsb
 * @property {number} bits
 * @property {'integer'|'boolean'} kind
 * @property {number|boolean} [default]
 */

/**
 * @typedef {object} InterfaceDef
 * @property {string} name
 * @property {string} type
 * @property {'source'|'sink'|'master'|'slave'|'pins'|'event_out'|'event_in'} role
 * @property {string} [clock]
 * @property {string} [label]
 * @property {string} [description]
 * @property {boolean} [mustServe]
 * @property {boolean} [externalOnly]
 * @property {string} [enabledBy]
 * @property {'default'|'open'|'zero'} [tieOff]
 * @property {string} [vector]
 * @property {Record<string, unknown>} [params]
 * @property {Record<string, string>} [widths]
 * @property {Record<string, string>} signals
 * @property {{signal: string, description?: string, fields: SidebandField[]}} [sideband]
 */

/**
 * @typedef {object} BlockDef
 * @property {string} id
 * @property {'core'|'module'|'olo'} kind
 * @property {string} name
 * @property {string} group
 * @property {string} source
 * @property {string} library
 * @property {string} entity
 * @property {string} path
 * @property {string} summary
 * @property {string} idPrefix
 * @property {string} [doc]
 * @property {string} [project]
 * @property {string[]} [notes]
 * @property {Record<string, unknown>[]} [rules]
 * @property {Record<string, unknown>[]} [constraints]
 * @property {GenericDef[]} generics
 * @property {{port: string, primary?: boolean, label?: string, description?: string, freqGeneric?: string}[]} clocks
 * @property {{port: string, dir?: string, active?: string, sync?: string, clock?: string}[]} resets
 * @property {InterfaceDef[]} interfaces
 * @property {{name: string, dir: string, vhdlType: string, width: string|null, default?: string}[]} ports
 * @property {{port: string, value: string}[]} [tieOffs]
 * @property {{id: string, name: string, summary: string, generics?: Record<string, unknown>}[]} [presets]
 */

/**
 * @typedef {object} PortView
 * @property {string} ref         interface reference within the instance, e.g. "S_Pkt" or "S_Tx[1]"
 * @property {InterfaceDef} itf
 * @property {TypeDef} type
 * @property {number | null} index
 * @property {'left'|'right'|'bottom'} side
 * @property {string} label
 * @property {{data?: number, keep?: number, user?: number}} widths
 */

export class CatalogError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = 'CatalogError';
  }
}

/** Upper limit of displayed vector elements (a vector generic can be larger in VHDL). */
export const MAX_VECTOR_PORTS = 32;

/** @param {InterfaceDef['role']} role */
export function sideOf(role) {
  if (role === 'pins') return 'bottom';
  if (role === 'sink' || role === 'slave' || role === 'event_in') return 'left';
  return 'right';
}

/** @param {InterfaceDef['role']} role */
export function isDriver(role) {
  return role === 'source' || role === 'master' || role === 'event_out';
}

export class Catalog {
  /** @param {any} json */
  constructor(json) {
    if (!json || json.format !== CATALOG_FORMAT) throw new CatalogError('Not a Composer catalog.');
    if (json.formatVersion !== CATALOG_VERSION) {
      throw new CatalogError(`Catalog format version ${json.formatVersion} is not supported.`);
    }
    /** @type {string} */
    this.id = String(json.id ?? '');
    /** @type {any[]} */
    this.sources = json.sources ?? [];
    /** @type {{id: string, name: string, description: string, groups: {id: string, name: string}[]}[]} */
    this.categories = json.categories ?? [];
    /** @type {Map<string, TypeDef>} */
    this.types = new Map((json.types ?? []).map((/** @type {TypeDef} */ t) => [t.id, t]));
    /** @type {Map<string, BlockDef>} */
    this.blocks = new Map((json.blocks ?? []).map((/** @type {BlockDef} */ b) => [b.id, b]));
    /** @type {Map<string, any>} */
    this.sourceById = new Map(this.sources.map((s) => [s.id, s]));
  }

  /** @param {string} id */
  block(id) {
    const b = this.blocks.get(id);
    if (!b) throw new CatalogError(`Unknown block "${id}".`);
    return b;
  }

  /** @param {string} id */
  type(id) {
    const t = this.types.get(id);
    if (!t) throw new CatalogError(`Unknown interface type "${id}".`);
    return t;
  }

  /** @param {string} blockId @param {string} name */
  interfaceDef(blockId, name) {
    return this.block(blockId).interfaces.find((i) => i.name === name);
  }

  /**
   * Category id of a block (cores or olo).
   * @param {BlockDef} b
   */
  categoryOf(b) {
    for (const c of this.categories) if (c.groups.some((g) => g.id === b.group)) return c.id;
    return '';
  }

  /**
   * Generic values of an instance: initial values of the catalog, then the preset, then the overrides.
   * @param {BlockDef} b
   * @param {Record<string, unknown>} [overrides]
   * @param {string} [presetId]
   * @returns {Record<string, unknown>}
   */
  genericValues(b, overrides = {}, presetId) {
    /** @type {Record<string, unknown>} */
    const out = {};
    for (const g of b.generics) {
      const v = initialValue(g);
      if (v !== undefined) out[g.name] = v;
    }
    const preset = presetId ? (b.presets ?? []).find((p) => p.id === presetId) : undefined;
    Object.assign(out, preset?.generics ?? {});
    for (const [k, v] of Object.entries(overrides)) if (b.generics.some((g) => g.name === k)) out[k] = v;
    return out;
  }

  /**
   * Values a design stores for an instance: those that differ from the catalog and preset.
   * @param {BlockDef} b
   * @param {Record<string, unknown>} values
   * @param {string} [presetId]
   */
  overridesOf(b, values, presetId) {
    const base = this.genericValues(b, {}, presetId);
    /** @type {Record<string, unknown>} */
    const out = {};
    for (const g of b.generics) {
      if (!(g.name in values)) continue;
      if (!sameValue(values[g.name], base[g.name])) out[g.name] = values[g.name];
    }
    return out;
  }

  /**
   * @param {BlockDef} b
   * @param {Record<string, unknown>} values
   */
  envFor(b, values) {
    const reals = new Set(b.generics.filter((g) => g.kind === 'real').map((g) => g.name.toLowerCase()));
    return makeEnv(values, reals);
  }

  /**
   * Interfaces of an instance as ports, with vectors expanded and disabled interfaces removed.
   * @param {BlockDef} b
   * @param {Record<string, unknown>} values
   * @returns {PortView[]}
   */
  ports(b, values) {
    const env = this.envFor(b, values);
    /** @type {PortView[]} */
    const out = [];
    for (const itf of b.interfaces) {
      if (itf.enabledBy && values[itf.enabledBy] === false) continue;
      const type = this.type(itf.type);
      /** @type {{data?: number, keep?: number, user?: number}} */
      const widths = {};
      for (const [k, w] of Object.entries(itf.widths ?? {})) {
        const v = tryEvaluate(w, env);
        if (v !== undefined) widths[/** @type {'data'|'keep'|'user'} */ (k)] = v;
      }
      const side = sideOf(itf.role);
      const label = itf.label ?? itf.name;
      if (itf.vector) {
        const n = tryEvaluate(itf.vector, env);
        const count = Math.max(0, Math.min(MAX_VECTOR_PORTS, Math.trunc(n ?? 1)));
        for (let i = 0; i < count; i += 1) {
          out.push({ ref: `${itf.name}[${i}]`, itf, type, index: i, side, label: `${label} ${i}`, widths });
        }
      } else {
        out.push({ ref: itf.name, itf, type, index: null, side, label, widths });
      }
    }
    return out;
  }

  /**
   * Port of an instance by its reference ("S_Pkt", "S_Tx[1]"), or undefined.
   * @param {BlockDef} b
   * @param {Record<string, unknown>} values
   * @param {string} ref
   */
  port(b, values, ref) {
    return this.ports(b, values).find((p) => p.ref === ref);
  }

  /**
   * Palette tree: categories with their groups and blocks, empty groups removed.
   */
  palette() {
    return this.categories.map((c) => ({
      id: c.id,
      name: c.name,
      description: c.description,
      groups: c.groups
        .map((g) => ({ id: g.id, name: g.name, blocks: [...this.blocks.values()].filter((b) => b.group === g.id) }))
        .filter((g) => g.blocks.length > 0),
    }));
  }
}

/**
 * Splits an endpoint reference "inst.S_Tx[1]" into its parts.
 * @param {string} ref
 * @returns {{ instance: string, port: string } | null}
 */
export function splitEndpoint(ref) {
  const m = /^([a-z](?:_?[a-z0-9])*)\.([A-Za-z]\w*(?:\[\d+\])?)$/.exec(ref);
  return m ? { instance: m[1], port: m[2] } : null;
}
